const WebmailCompose = ({ show, onClose, initialTo, initialSubject, initialBody, onSuccess }: Props) => {
  const { addToast } = useToast();
  const [to, setTo] = useState('');
  const [cc, setCc] = useState('');
  const [bcc, setBcc] = useState('');
  const [showCc, setShowCc] = useState(false);
  const [showBcc, setShowBcc] = useState(false);
  const [subject, setSubject] = useState('');
  const [sending, setSending] = useState(false);
  const [attachments, setAttachments] = useState<File[]>([]);

  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (show) {
        setTo(initialTo || '');
        setSubject(initialSubject || '');
        setCc('');
        setBcc('');
        setAttachments([]);

        // Initialize Editor Content
        if(editorRef.current) {
             editorRef.current.innerHTML = initialBody || '';

             // Focus handling with slight delay to ensure render
             setTimeout(() => {
                 if (editorRef.current) {
                     editorRef.current.focus();

                     // If replying (initialBody present), ensure cursor is at the very top
                     if (initialBody) {
                         const selection = window.getSelection();
                         const range = document.createRange();
                         range.setStart(editorRef.current, 0);
                         range.collapse(true);
                         selection?.removeAllRanges();
                         selection?.addRange(range);
                     }
                 }
             }, 50);
        }
    }
  }, [show, initialTo, initialSubject, initialBody]);

  if (!show) return null;

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
        const filesArray = Array.from(e.target.files);
        setAttachments(prev => [...prev, ...filesArray]);
    }
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
  };

  const execCmd = (cmd: string, val?: string) => {
      document.execCommand(cmd, false, val);
      if(editorRef.current) editorRef.current.focus();
  };

  const handleInsertImage = () => {
      const url = prompt("Enter Image URL:");
      if(url) execCmd('insertImage', url);
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!editorRef.current) return;

    setSending(true);
    const htmlBody = editorRef.current.innerHTML;

    try {
      const attachmentPayload = await Promise.all(attachments.map(async (file) => ({
          filename: file.name,
          contentType: file.type,
          content: await fileToBase64(file)
      })));

      await api.post('/api/webmail/send', {
        to,
        cc,
        bcc,
        subject,
        htmlBody,
        attachments: attachmentPayload
      });

      onSuccess();
      onClose();
      addToast('Message sent successfully', 'success');
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Failed to send message', 'error');
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-hidden flex items-end sm:items-center justify-center p-0 sm:p-4 bg-gray-900/30 backdrop-blur-sm">
        <div className="bg-white w-full sm:max-w-3xl h-full sm:h-[85vh] sm:rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 duration-200">
            <div className="flex items-center justify-between px-6 py-3 border-b border-gray-200 bg-gray-50 flex-shrink-0">
                <h3 className="text-lg font-bold text-gray-900">New Message</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors bg-white rounded-full p-1 border border-gray-200">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>

            <form onSubmit={handleSend} className="flex-1 flex flex-col min-h-0">
                <div className="px-4 sm:px-6 py-4 space-y-4 overflow-y-auto flex-1">
                    <div className="space-y-2">
                        <div className="flex items-center gap-2 border-b border-gray-100 pb-2">
                            <span className="text-sm font-semibold text-gray-500 w-10">To</span>
                            <input 
                                type="text" 
                                value={to} 
                                onChange={e => setTo(e.target.value)}
                                className="flex-1 outline-none text-sm text-gray-800"
                                placeholder="recipient@example.com"
                                required 
                            />
                            <div className="flex gap-2 text-xs text-gray-500">
                                <button type="button" onClick={() => setShowCc(!showCc)} className="hover:text-gray-800 hover:underline">Cc</button>
                                <button type="button" onClick={() => setShowBcc(!showBcc)} className="hover:text-gray-800 hover:underline">Bcc</button>
                            </div>
                        </div>
                        {showCc && <div className="flex items-center gap-2 border-b border-gray-100 pb-2 animate-in fade-in slide-in-from-top-1"><span className="text-sm font-semibold text-gray-500 w-10">Cc</span><input type="text" value={cc} onChange={e => setCc(e.target.value)} className="flex-1 outline-none text-sm text-gray-800" placeholder="cc@example.com"/></div>}
                        {showBcc && <div className="flex items-center gap-2 border-b border-gray-100 pb-2 animate-in fade-in slide-in-from-top-1"><span className="text-sm font-semibold text-gray-500 w-10">Bcc</span><input type="text" value={bcc} onChange={e => setBcc(e.target.value)} className="flex-1 outline-none text-sm text-gray-800" placeholder="bcc@example.com"/></div>}
                        <div className="flex items-center gap-2 border-b border-gray-100 pb-2"><span className="text-sm font-semibold text-gray-500 w-10">Subject</span><input type="text" value={subject} onChange={e => setSubject(e.target.value)} className="flex-1 outline-none text-sm text-gray-800 font-medium" placeholder="Subject"/></div>
                    </div>

                    <div className="flex flex-col h-full min-h-[300px] border border-gray-200 rounded-lg overflow-hidden bg-white">
                        <RichTextToolbar onCmd={execCmd} onImage={handleInsertImage} />
                        <div ref={editorRef} contentEditable id="compose-editor" className="flex-1 p-4 outline-none overflow-y-auto text-sm font-sans" style={{ minHeight: '200px' }}></div>
                    </div>

                    {attachments.length > 0 && (
                        <div className="flex flex-wrap gap-2 pt-2">
                            {attachments.map((file, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-gray-100 px-3 py-1.5 rounded-full text-xs text-gray-700 border border-gray-200">
                                    <svg className="w-3 h-3 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                                    <span className="max-w-[150px] truncate">{file.name}</span>
                                    <button type="button" onClick={() => removeAttachment(idx)} className="hover:text-red-500"><svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex justify-between items-center pb-safe">
                    <div className="flex items-center gap-3">
                         <input type="file" multiple ref={fileInputRef} className="hidden" onChange={handleFileSelect} />
                         <button type="button" onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-gray-900 hover:bg-gray-200 p-2 rounded-full transition-colors" title="Attach File"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg></button>
                    </div>
                    <div className="flex items-center gap-3">
                        <button type="button" onClick={onClose} className="text-sm font-medium text-gray-500 hover:text-gray-800 transition-colors">Discard</button>
                        <button type="submit" disabled={sending} className="bg-green-600 text-white px-6 py-2 rounded-lg text-sm font-bold hover:bg-green-700 transition-colors disabled:opacity-50 flex items-center gap-2 shadow-sm">{sending && <Spinner />} Send</button>
                    </div>
                </div>
            </form>
        </div>
    </div>
  );
};

export default WebmailCompose;

import React, { useState, useEffect, useCallback } from 'react';
import api from '../api';
import { User, EmailMessage } from '../types';
import { useToast } from '../components/ToastContext';

// Import New Modular Components
import WebmailSidebar from './webmail/WebmailSidebar';
import WebmailMessageList from './webmail/WebmailMessageList';
import WebmailReadingPane from './webmail/WebmailReadingPane';
import WebmailMobileNav from './webmail/WebmailMobileNav';
import WebmailCompose from './webmail/WebmailCompose';
import WebmailSettings from './webmail/WebmailSettings';

const WebmailView = ({ user, onLogout }: { user: User, onLogout: () => void }) => {
  const { addToast } = useToast();

  // Data State
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [selectedMsg, setSelectedMsg] = useState<EmailMessage | null>(null);

  // View State
  const [view, setView] = useState<'inbox' | 'sent'>('inbox');
  const [loadingMessages, setLoadingMessages] = useState(false);

  // Pagination State
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalMessages, setTotalMessages] = useState(0);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modals State
  const [showCompose, setShowCompose] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Compose Pre-fill State (for replies)
  const [composeTo, setComposeTo] = useState('');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');

  // Fetch Messages
  const fetchMessages = useCallback(async (isPolling = false) => {
    if (!isPolling) setLoadingMessages(true);
    try {
      const res = await api.get('/api/webmail/messages', {
        params: { folder: view, page, limit: 20 }
      });
      setMessages(res.data.messages);
      setTotalPages(res.data.pagination.pages);
      setTotalMessages(res.data.pagination.total);
    } catch (err) {
      console.error(err);
    } finally {
      if (!isPolling) setLoadingMessages(false);
    }
  }, [view, page]);

  useEffect(() => {
    fetchMessages();
    let int: any;
    if (page === 1) {
        int = setInterval(() => fetchMessages(true), 15000);
    }
    return () => clearInterval(int);
  }, [fetchMessages, page]);

  // Reset state on view change
  useEffect(() => {
      setPage(1);
      setSelectedIds(new Set());
      setSelectedMsg(null);
  }, [view]);

  // Handlers
  const handleSelectMessage = async (msg: EmailMessage) => {
    setSelectedMsg(msg);
    if (!msg.is_read) {
        setMessages(prev => prev.map(m => m._id === msg._id ? { ...m, is_read: true } : m));
        try { await api.patch(`/api/webmail/messages/${msg._id}/read`); } catch (err) {}
    }
  };

  const toggleSelection = (id: string, e: React.SyntheticEvent) => {
    e.stopPropagation();
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === messages.length) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(messages.map(m => m._id)));
    }
  };

  const handleBatchDelete = async () => {
    if(!confirm(`Delete ${selectedIds.size} messages?`)) return;
    try {
        await api.post('/api/webmail/messages/batch-delete', { ids: Array.from(selectedIds) });
        addToast('Messages deleted', 'success');
        setSelectedIds(new Set());
        fetchMessages();
        if (selectedMsg && selectedIds.has(selectedMsg._id)) {
            setSelectedMsg(null);
        }
    } catch (err) {
        addToast('Failed to delete messages', 'error');
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if(!confirm('Delete this message?')) return;
    try {
        await api.delete(`/api/webmail/messages/${id}`);
        setMessages(prev => prev.filter(m => m._id !== id));
        if (selectedMsg?._id === id) setSelectedMsg(null);
        addToast('Message deleted', 'success');
    } catch(err) {
        addToast('Failed to delete message', 'error');
        fetchMessages();
    }
  };

  const handleReply = () => {
    if (!selectedMsg) return;
    const replyTo = view === 'inbox' ? selectedMsg.from : selectedMsg.to;
    const replySubject = selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`;

    const dateStr = new Date(selectedMsg.created_at).toLocaleString();
    const cleanFrom = selectedMsg.from.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const originalContent = selectedMsg.html_body || selectedMsg.text_body.replace(/\n/g, '<br>');

    // Standard blockquote style for email replies
    const quoteHtml = `<p><br></p><p><br></p><blockquote style="margin: 0 0 0 0.8ex; border-left: 1px #ccc solid; padding-left: 1ex;">
    On ${dateStr}, ${cleanFrom} wrote:<br>
    ${originalContent}
    </blockquote>`;

    setComposeTo(replyTo);
    setComposeSubject(replySubject);
    setComposeBody(quoteHtml);
    setShowCompose(true);
  };

  const handleCompose = () => {
      setComposeTo('');
      setComposeSubject('');
      setComposeBody('');
      setShowCompose(true);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* 1. Desktop Sidebar */}
      <WebmailSidebar 
        user={user}
        view={view}
        messages={messages}
        onCompose={handleCompose}
        onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
        onSettings={() => setShowSettings(true)}
        onLogout={onLogout}
      />

      {/* 2. Message List */}
      <WebmailMessageList 
        user={user}
        messages={messages}
        selectedMsg={selectedMsg}
        onSelect={handleSelectMessage}
        view={view}
        loading={loadingMessages}
        onRefresh={() => fetchMessages()}
        selectedIds={selectedIds}
        toggleSelectAll={toggleSelectAll}
        toggleSelection={toggleSelection}
        onBatchDelete={handleBatchDelete}
        page={page}
        totalPages={totalPages}
        setPage={setPage}
        totalMessages={totalMessages}
      />

      {/* 3. Reading Pane */}
      <WebmailReadingPane 
        selectedMsg={selectedMsg}
        onBack={() => setSelectedMsg(null)}
        onDelete={handleDelete}
        onReply={handleReply}
      />

      {/* 4. Mobile Bottom Navigation */}
      {/* Hide nav if reading a message to allow full screen reading */}
      {!selectedMsg && (
          <WebmailMobileNav 
            view={view}
            onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
            onCompose={handleCompose}
            onSettings={() => setShowSettings(true)}
            showSettings={showSettings}
          />
      )}

      {/* 5. Compose Modal */}
      <WebmailCompose 
        show={showCompose}
        onClose={() => setShowCompose(false)}
        initialTo={composeTo}
        initialSubject={composeSubject}
        initialBody={composeBody}
        onSuccess={() => {
            if (view === 'sent') fetchMessages();
        }}
      />

      {/* 6. Settings Modal */}
      {showSettings && (
        <WebmailSettings 
            user={user}
            onClose={() => setShowSettings(false)}
            onLogout={onLogout}
        />
      )}

    </div>
  );
};

export default WebmailView;

const dns = require('dns').promises;
const nodemailer = require('nodemailer');
const Mailbox = require('../models/Mailbox');
const Domain = require('../models/Domain');
const Client = require('../models/Client');
const EmailMessage = require('../models/EmailMessage');
const SystemConfig = require('../models/SystemConfig');
const logger = require('../config/logger');

/**
 * Helper: Extract pure email from "Name <email>" format
 */
const extractEmail = (fullAddress) => {
    if (!fullAddress) return '';
    const match = fullAddress.match(/<([^>]+)>/);
    return (match ? match[1] : fullAddress).toLowerCase().trim();
};

/**
 * Helper: Send email to external server
 */
const deliverExternal = async (senderEmail, recipientEmail, subject, text, html, options = {}) => {
  try {
    const cleanRecipient = extractEmail(recipientEmail);
    const cleanSender = extractEmail(senderEmail);

    const recipientDomain = cleanRecipient.split('@')[1];
    if (!recipientDomain) throw new Error('Invalid recipient domain');

    // 1. Resolve MX Records
    const mxRecords = await dns.resolveMx(recipientDomain);
    if (!mxRecords || mxRecords.length === 0) throw new Error('No MX records found for domain');

    // Sort by priority (lowest number first)
    const bestMx = mxRecords.sort((a, b) => a.priority - b.priority)[0].exchange;

    logger.info(`Resolving delivery for ${cleanRecipient}: via ${bestMx}`);

    // 2. Prepare DKIM Signing
    let dkimOptions = undefined;
    const senderMailbox = await Mailbox.findOne({ email: cleanSender }).populate('domain_id');

    if (senderMailbox && senderMailbox.domain_id && senderMailbox.domain_id.dkim_private_key) {
      dkimOptions = {
        domainName: senderMailbox.domain_id.name,
        keySelector: 'default',
        privateKey: senderMailbox.domain_id.dkim_private_key
      };
    } else {
         const senderDomainPart = cleanSender.split('@')[1];
         if (senderDomainPart) {
             const senderDomain = await Domain.findOne({ name: senderDomainPart });
             if (senderDomain && senderDomain.dkim_private_key) {
                 dkimOptions = {
                    domainName: senderDomain.name,
                    keySelector: 'default',
                    privateKey: senderDomain.dkim_private_key
                };
             }
         }
    }

    // 3. Get System Config for HELO
    let heloName = process.env.MY_HOSTNAME || 'smtp-server.local';
    try {
        const config = await SystemConfig.findOne({ singleton: true });
        if (config && config.smtp_hostname) {
            heloName = config.smtp_hostname;
        }
    } catch(e) { /* Fallback */ }

    // 4. Create Transporter
    const transporter = nodemailer.createTransport({
      host: bestMx,
      port: 25,
      secure: false,
      tls: { rejectUnauthorized: false },
      name: heloName,
      dkim: dkimOptions
    });

    // 5. Send
    await transporter.sendMail({
      from: senderEmail, 
      to: recipientEmail,
      cc: options.cc,
      bcc: options.bcc,
      subject: subject,
      text: text,
      html: html,
      attachments: options.attachments
    });

    logger.info(`External Delivery Success: ${cleanRecipient}`);
    return true;
  } catch (error) {
    logger.error(`External Delivery Failed to ${recipientEmail}: ${error.message}`);
    return false;
  }
};

/**
 * Delivers an email (System or User) handling both local and external recipients.
 */
const sendEmail = async (from, to, subject, text, html, options = {}) => {
    try {
        const cleanTo = extractEmail(to);
        const recipientMailbox = await Mailbox.findOne({ email: cleanTo });

        if (recipientMailbox) {
            // --- LOCAL DELIVERY (Mailbox to Mailbox on same server) ---
            await EmailMessage.create({
                mailbox_id: recipientMailbox._id,
                direction: 'inbound',
                from: from, // Keep full "Name <email>" string for UI
                to: cleanTo,
                cc: options.cc || '',
                bcc: options.bcc || '',
                subject: subject || '',
                text_body: text || '',
                html_body: html || '',
                has_attachments: options.attachments && options.attachments.length > 0,
                attachments: options.attachments || [], // CRITICAL FIX: Save the actual files
                folder: 'inbox',
                is_read: false
            });
            logger.info(`Internal Delivery: ${from} -> ${cleanTo}`);
            return true;
        } else {
            // --- EXTERNAL DELIVERY (To Gmail, Outlook, etc) ---
            return await deliverExternal(from, to, subject, text, html, options);
        }
    } catch (err) {
        logger.error('Email Service Error:', err);
        return false;
    }
};

const sendSystemEmail = async (to, subject, text, html) => {
    let fromEmail = 'noreply@system.local';
    let fromName = 'Eeina Security';

    try {
        const admin = await Client.findOne().sort({ created_at: 1 });
        if (admin && admin.company_name) fromName = admin.company_name;

        const validDomain = await Domain.findOne({ is_verified: true });
        if (validDomain) {
            fromEmail = `noreply@${validDomain.name}`;
        } else {
            const config = await SystemConfig.findOne({ singleton: true });
            if (config && config.system_email_address && !config.system_email_address.includes('system.local')) {
                fromEmail = config.system_email_address;
            }
        }
    } catch (e) {
        logger.error('System Email Sender Error:', e);
    }

    const from = `"${fromName}" <${fromEmail}>`;
    return await sendEmail(from, to, subject, text, html);
};

module.exports = {
    deliverExternal,
    sendEmail,
    sendSystemEmail
};

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const { authenticateWebmail } = require('../middleware/auth');
const logger = require('../config/logger');
const emailService = require('../services/email.service');

// Helper to safely convert base64 strings (with or without data prefix) to Buffers
const base64ToBuffer = (base64String) => {
    if (!base64String) return Buffer.alloc(0);
    const parts = base64String.split('base64,');
    const raw = parts.length > 1 ? parts[1] : parts[0];
    return Buffer.from(raw, 'base64');
};

// Webmail Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email: email.toLowerCase() });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });

    res.json({ 
        token, 
        email: mailbox.email,
        first_name: mailbox.first_name,
        last_name: mailbox.last_name
    });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Change Password
router.put('/password', authenticateWebmail, async (req, res) => {
  try {
    const { currentPassword, newPassword } = req.body;
    if (!newPassword || newPassword.length < 6) return res.status(400).json({ error: 'New password must be at least 6 characters' });

    const mailbox = await Mailbox.findById(req.user.mailbox_id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });

    const isMatch = await bcrypt.compare(currentPassword, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Incorrect current password' });

    const salt = await bcrypt.genSalt(10);
    mailbox.password_hash = await bcrypt.hash(newPassword, salt);
    await mailbox.save();

    res.json({ message: 'Password updated successfully' });
  } catch (err) {
    logger.error('Webmail Password Update Error:', err);
    res.status(500).json({ error: 'Failed to update password' });
  }
});

// Get Webmail Profile
router.get('/profile', authenticateWebmail, async (req, res) => {
    try {
        const mailbox = await Mailbox.findById(req.user.mailbox_id);
        if(!mailbox) return res.status(404).json({error: "Mailbox not found"});
        res.json({
            email: mailbox.email,
            first_name: mailbox.first_name,
            last_name: mailbox.last_name,
            recovery_email: mailbox.recovery_email
        });
    } catch(err) {
        res.status(500).json({error: "Server Error"});
    }
});

// Webmail Messages (Paginated)
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 20;
    const folder = req.query.folder || 'inbox';
    const skip = (page - 1) * limit;

    const query = { mailbox_id: req.user.mailbox_id, folder: folder };

    const [messages, total] = await Promise.all([
        EmailMessage.find(query)
          .select('-attachments.content') // Exclude binary to keep list light
          .sort({ created_at: -1 })
          .skip(skip)
          .limit(limit),
        EmailMessage.countDocuments(query)
    ]);

    res.json({
        messages,
        pagination: { total, page, pages: Math.ceil(total / limit) }
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// Download Attachment
router.get('/messages/:id/download/:filename', authenticateWebmail, async (req, res) => {
  try {
    const message = await EmailMessage.findOne({ _id: req.params.id, mailbox_id: req.user.mailbox_id });
    if (!message) return res.status(404).json({ error: 'Message not found' });

    const attachment = message.attachments.find(att => att.filename === req.params.filename);
    if (!attachment) return res.status(404).json({ error: 'Attachment not found' });

    res.setHeader('Content-Type', attachment.contentType || 'application/octet-stream');
    res.setHeader('Content-Disposition', `attachment; filename="${attachment.filename}"`);
    res.send(attachment.content);
  } catch (err) {
    logger.error('Download Error:', err);
    res.status(500).json({ error: 'Failed to download attachment' });
  }
});

// Mark Message as Read
router.patch('/messages/:id/read', authenticateWebmail, async (req, res) => {
    try {
        const msg = await EmailMessage.findOneAndUpdate(
            { _id: req.params.id, mailbox_id: req.user.mailbox_id },
            { is_read: true },
            { new: true }
        ).select('-attachments.content');
        if (!msg) return res.status(404).json({ error: 'Message not found' });
        res.json(msg);
    } catch (err) {
        res.status(500).json({ error: 'Failed to update message' });
    }
});

// Batch Delete Messages
router.post('/messages/batch-delete', authenticateWebmail, async (req, res) => {
    try {
        const { ids } = req.body;
        if (!ids || !Array.isArray(ids)) return res.status(400).json({ error: 'Invalid IDs provided' });
        await EmailMessage.deleteMany({ _id: { $in: ids }, mailbox_id: req.user.mailbox_id });
        res.json({ message: 'Messages deleted' });
    } catch (err) {
        logger.error('Batch Delete Error:', err);
        res.status(500).json({ error: 'Failed to delete messages' });
    }
});

// Delete Single Message
router.delete('/messages/:id', authenticateWebmail, async (req, res) => {
  try {
    const msg = await EmailMessage.findOneAndDelete({ _id: req.params.id, mailbox_id: req.user.mailbox_id });
    if (!msg) return res.status(404).json({ error: 'Message not found' });
    res.json({ message: 'Message deleted successfully' });
  } catch (err) {
    logger.error('Delete Message Error:', err);
    res.status(500).json({ error: 'Failed to delete message' });
  }
});

// Send Email
router.post('/send', authenticateWebmail, async (req, res) => {
  try {
    const { to, cc, bcc, subject, htmlBody, attachments } = req.body;
    if (!to) return res.status(400).json({ error: 'Recipient required' });

    const senderMailboxId = req.user.mailbox_id;
    const senderEmail = req.user.email;
    const sender = await Mailbox.findById(senderMailboxId);

    let fromHeader = senderEmail;
    if (sender && (sender.first_name || sender.last_name)) {
        const fullName = `${sender.first_name || ''} ${sender.last_name || ''}`.trim();
        fromHeader = `"${fullName}" <${senderEmail}>`;
    }

    const safeHtml = `<div style="font-family: sans-serif;">${htmlBody}</div>`;
    const plainText = htmlBody.replace(/<[^>]+>/g, ' ');

    // Robust attachment processing
    const processedAttachments = attachments ? attachments.map(att => {
        const buffer = base64ToBuffer(att.content);
        return {
            filename: att.filename,
            content: buffer,
            contentType: att.contentType,
            size: buffer.length
        };
    }) : [];

    // 1. Save to Sender's Sent Folder
    await EmailMessage.create({
      mailbox_id: senderMailboxId,
      direction: 'outbound',
      from: fromHeader,
      to,
      cc: cc || '',
      bcc: bcc || '',
      subject: subject || '',
      text_body: plainText,
      html_body: safeHtml,
      has_attachments: processedAttachments.length > 0,
      attachments: processedAttachments,
      folder: 'sent',
      is_read: true
    });

    // 2. Process Delivery
    const recipients = to.split(/[;,]+/).map(r => r.trim()).filter(r => r);
    const ccRecipients = cc ? cc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : [];
    const bccRecipients = bcc ? bcc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : [];

    const allRecipients = new Set([...recipients, ...ccRecipients, ...bccRecipients]);

    for (const recipientEmail of allRecipients) {
      await emailService.sendEmail(fromHeader, recipientEmail, subject, plainText, safeHtml, {
        cc,
        bcc,
        attachments: processedAttachments
      });
    }

    res.json({ message: 'Email sent successfully' });
  } catch (err) {
    logger.error('Send Error:', err);
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = router;

