  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email: email.toLowerCase() });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });
    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });
    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
    res.json({ token, email: mailbox.email, first_name: mailbox.first_name, last_name: mailbox.last_name });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Change Password
router.put('/password', authenticateWebmail, async (req, res) => {
  try {
    const { currentPassword, newPassword } = req.body;
    if (!newPassword || newPassword.length < 6) return res.status(400).json({ error: 'New password must be at least 6 characters' });
    const mailbox = await Mailbox.findById(req.user.mailbox_id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });
    const isMatch = await bcrypt.compare(currentPassword, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Incorrect current password' });
    const salt = await bcrypt.genSalt(10);
    mailbox.password_hash = await bcrypt.hash(newPassword, salt);
    await mailbox.save();
    res.json({ message: 'Password updated successfully' });
  } catch (err) {
    logger.error('Webmail Password Update Error:', err);
    res.status(500).json({ error: 'Failed to update password' });
  }
});

// Get Webmail Profile
router.get('/profile', authenticateWebmail, async (req, res) => {
    try {
        const mailbox = await Mailbox.findById(req.user.mailbox_id);
        if(!mailbox) return res.status(404).json({error: "Mailbox not found"});
        res.json({ email: mailbox.email, first_name: mailbox.first_name, last_name: mailbox.last_name, recovery_email: mailbox.recovery_email });
    } catch(err) { res.status(500).json({error: "Server Error"}); }
});

// Get Messages
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 20;
    const folder = req.query.folder || 'inbox';
    const skip = (page - 1) * limit;
    const query = { mailbox_id: req.user.mailbox_id, folder: folder };
    const [messages, total] = await Promise.all([
        EmailMessage.find(query).sort({ created_at: -1 }).skip(skip).limit(limit),
        EmailMessage.countDocuments(query)
    ]);
    res.json({ messages, pagination: { total, page, pages: Math.ceil(total / limit) } });
  } catch (err) { res.status(500).json({ error: 'Failed to fetch messages' }); }
});

// Download Attachment from GridFS
router.get('/messages/:id/download/:filename', authenticateWebmail, async (req, res) => {
  try {
    const message = await EmailMessage.findOne({ _id: req.params.id, mailbox_id: req.user.mailbox_id });
    if (!message) return res.status(404).json({ error: 'Message not found' });
    const att = message.attachments.find(a => a.filename === req.params.filename);
    if (!att || !att.gridfs_id) return res.status(404).json({ error: 'Attachment not found' });

    res.setHeader('Content-Type', att.contentType || 'application/octet-stream');
    res.setHeader('Content-Disposition', `attachment; filename="${att.filename}"`);

    const downloadStream = bucket.openDownloadStream(att.gridfs_id);
    downloadStream.on('error', (err) => {
        logger.error('GridFS Stream Error:', err);
        res.status(500).end();
    });
    downloadStream.pipe(res);
  } catch (err) {
    logger.error('Download Error:', err);
    res.status(500).json({ error: 'Failed to download attachment' });
  }
});

// Mark Message as Read
router.patch('/messages/:id/read', authenticateWebmail, async (req, res) => {
    try {
        const msg = await EmailMessage.findOneAndUpdate(
            { _id: req.params.id, mailbox_id: req.user.mailbox_id },
            { is_read: true },
            { new: true }
        );
        res.json(msg);
    } catch (err) { res.status(500).json({ error: 'Failed to update message' }); }
});

// Batch Delete Messages
router.post('/messages/batch-delete', authenticateWebmail, async (req, res) => {
    try {
        const { ids } = req.body;
        const messages = await EmailMessage.find({ _id: { $in: ids }, mailbox_id: req.user.mailbox_id });
        for (const msg of messages) {
            for (const att of msg.attachments) {
                if (att.gridfs_id) await bucket.delete(att.gridfs_id).catch(() => {});
            }
        }
        await EmailMessage.deleteMany({ _id: { $in: ids }, mailbox_id: req.user.mailbox_id });
        res.json({ message: 'Messages deleted' });
    } catch (err) { res.status(500).json({ error: 'Failed to delete messages' }); }
});

// Delete Single Message
router.delete('/messages/:id', authenticateWebmail, async (req, res) => {
  try {
    const msg = await EmailMessage.findOne({ _id: req.params.id, mailbox_id: req.user.mailbox_id });
    if (msg) {
        for (const att of msg.attachments) {
            if (att.gridfs_id) await bucket.delete(att.gridfs_id).catch(() => {});
        }
        await msg.deleteOne();
    }
    res.json({ message: 'Message deleted successfully' });
  } catch (err) { res.status(500).json({ error: 'Failed to delete message' }); }
});

// Send Email (Supports Large Files via Multipart & GridFS Streaming)
router.post('/send', authenticateWebmail, upload.array('attachments'), async (req, res) => {
  const filesToCleanup = req.files || [];
  try {
    const { to, cc, bcc, subject, htmlBody } = req.body;
    const sender = await Mailbox.findById(req.user.mailbox_id);
    const fromHeader = sender && (sender.first_name || sender.last_name) 
        ? `"${sender.first_name || ''} ${sender.last_name || ''}".trim() <${req.user.email}>`
        : req.user.email;

    const safeHtml = `<div style="font-family: sans-serif;">${htmlBody}</div>`;
    const plainText = htmlBody.replace(/<[^>]+>/g, ' ');

    // Upload attachments to GridFS from Disk temp path
    const processedAttachments = [];
    if (filesToCleanup.length > 0) {
        for (const file of filesToCleanup) {
            const uploadStream = bucket.openUploadStream(file.originalname, {
                contentType: file.mimetype
            });

            await new Promise((resolve, reject) => {
                const fsStream = fs.createReadStream(file.path);
                fsStream.pipe(uploadStream)
                    .on('finish', resolve)
                    .on('error', reject);
            });

            processedAttachments.push({
                filename: file.originalname,
                contentType: file.mimetype,
                gridfs_id: uploadStream.id,
                size: file.size
            });
        }
    }

    // Save to Sent folder
    await EmailMessage.create({
      mailbox_id: req.user.mailbox_id,
      direction: 'outbound',
      from: fromHeader,
      to, cc: cc || '', bcc: bcc || '',
      subject: subject || '',
      text_body: plainText,
      html_body: safeHtml,
      has_attachments: processedAttachments.length > 0,
      attachments: processedAttachments,
      folder: 'sent',
      is_read: true
    });

    const allRecipients = new Set([
        ...to.split(/[;,]+/).map(r => r.trim()).filter(r => r),
        ...(cc ? cc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : []),
        ...(bcc ? bcc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : [])
    ]);

    for (const recipientEmail of allRecipients) {
        await emailService.sendEmail(fromHeader, recipientEmail, subject, plainText, safeHtml, {
            cc, bcc, attachments: processedAttachments
        });
    }

    // Cleanup all temp files on success
    filesToCleanup.forEach(f => fs.unlink(f.path, () => {}));
    res.json({ message: 'Email sent successfully' });
  } catch (err) {
    // Cleanup any files remaining on error
    filesToCleanup.forEach(f => fs.unlink(f.path, () => {}));
    logger.error('Send Error:', err);
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = router;

import React, { useState, useRef, useEffect } from 'react';
import api from '../../api';
import Spinner from '../../components/Spinner';
import { useToast } from '../../components/ToastContext';

interface Props {
  show: boolean;
  onClose: () => void;
  initialTo?: string;
  initialSubject?: string;
  initialBody?: string;
  onSuccess: () => void;
}

const MAX_FILE_SIZE_MB = 250; 

const formatSize = (bytes: number) => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
};

const RichTextToolbar = ({ onCmd, onImage }: { onCmd: (cmd: string, val?: string) => void, onImage: () => void }) => {
    const Btn = ({ cmd, label, val }: any) => (
        <button 
            type="button" 
            onMouseDown={(e) => { e.preventDefault(); onCmd(cmd, val); }}
            className="p-1.5 text-gray-500 hover:text-gray-900 hover:bg-gray-100 rounded transition-colors"
            title={label}
        >
            {label}
        </button>
    );

    return (
        <div className="flex items-center gap-1 border-b border-gray-200 p-2 bg-gray-50 overflow-x-auto">
            <Btn cmd="bold" label={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 12h8a4 4 0 100-8H6v8zm0 0h8a4 4 0 110 8H6v-8z" /></svg>} />
            <Btn cmd="italic" label={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" /></svg>} />
            <Btn cmd="underline" label={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>} />
            <div className="w-px h-4 bg-gray-300 mx-1"></div>
            <Btn cmd="insertUnorderedList" label={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>} />
            <Btn cmd="insertOrderedList" label={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 20h14M7 4h14M21 12H7M3 20h.01M3 4h.01M3 12h.01" /></svg>} />
            <div className="w-px h-4 bg-gray-300 mx-1"></div>
            <button 
                type="button"
                onMouseDown={(e) => { e.preventDefault(); onImage(); }}
                className="p-1.5 text-gray-500 hover:text-gray-900 hover:bg-gray-100 rounded transition-colors"
                title="Insert Image"
            >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>
        </div>
    );
};

const WebmailCompose = ({ show, onClose, initialTo, initialSubject, initialBody, onSuccess }: Props) => {
  const { addToast } = useToast();
  const [to, setTo] = useState('');
  const [cc, setCc] = useState('');
  const [bcc, setBcc] = useState('');
  const [showCc, setShowCc] = useState(false);
  const [showBcc, setShowBcc] = useState(false);
  const [subject, setSubject] = useState('');
  const [sending, setSending] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [attachments, setAttachments] = useState<File[]>([]);

  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (show) {
        setTo(initialTo || '');
        setSubject(initialSubject || '');
        setCc('');
        setBcc('');
        setAttachments([]);
        setUploadProgress(0);

        if(editorRef.current) {
             editorRef.current.innerHTML = initialBody || '';
             setTimeout(() => {
                 if (editorRef.current) {
                     editorRef.current.focus();
                     if (initialBody) {
                         const selection = window.getSelection();
                         const range = document.createRange();
                         range.setStart(editorRef.current, 0);
                         range.collapse(true);
                         selection?.removeAllRanges();
                         selection?.addRange(range);
                     }
                 }
             }, 50);
        }
    }
  }, [show, initialTo, initialSubject, initialBody]);

  if (!show) return null;

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
        const filesArray = Array.from(e.target.files) as File[];
        const oversizedFiles = filesArray.filter(f => f.size > MAX_FILE_SIZE_MB * 1024 * 1024);

        if (oversizedFiles.length > 0) {
            addToast(`Files exceed ${MAX_FILE_SIZE_MB}MB limit`, 'error');
            const validFiles = filesArray.filter(f => f.size <= MAX_FILE_SIZE_MB * 1024 * 1024);
            setAttachments(prev => [...prev, ...validFiles]);
        } else {
            setAttachments(prev => [...prev, ...filesArray]);
        }
    }
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  const execCmd = (cmd: string, val?: string) => {
      document.execCommand(cmd, false, val);
      if(editorRef.current) editorRef.current.focus();
  };

  const handleInsertImage = () => {
      const url = prompt("Enter Image URL:");
      if(url) execCmd('insertImage', url);
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!editorRef.current) return;

    setSending(true);
    setUploadProgress(0);
    const htmlBody = editorRef.current.innerHTML;

    try {
      const formData = new FormData();
      formData.append('to', to);
      formData.append('cc', cc);
      formData.append('bcc', bcc);
      formData.append('subject', subject);
      formData.append('htmlBody', htmlBody);

      attachments.forEach(file => {
          formData.append('attachments', file);
      });

      await api.post('/api/webmail/send', formData, {
          headers: { 'Content-Type': 'multipart/form-data' },
          onUploadProgress: (progressEvent) => {
            const percentCompleted = Math.round((progressEvent.loaded * 100) / (progressEvent.total || 1));
            setUploadProgress(percentCompleted);
          }
      });

      onSuccess();
      onClose();
      addToast('Message sent successfully', 'success');
    } catch (err: any) {
      console.error("Upload failed", err);
      // Explicit detection for Nginx/Proxy limit errors
      if (err.response?.status === 413 || (err.code === 'ERR_NETWORK' && attachments.some(a => a.size > 1024 * 1024))) {
          addToast('CRITICAL: Nginx is blocking this upload. Add "client_max_body_size 250M;" to Nginx config.', 'error');
      } else {
          addToast(err.response?.data?.error || 'Server error during large upload.', 'error');
      }
    } finally {
      setSending(false);
      setUploadProgress(0);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-hidden flex items-end sm:items-center justify-center p-0 sm:p-4 bg-gray-900/30 backdrop-blur-sm">
        <div className="bg-white w-full sm:max-w-3xl h-full sm:h-[85vh] sm:rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 duration-200">
            <div className="flex items-center justify-between px-6 py-3 border-b border-gray-200 bg-gray-50 flex-shrink-0">
                <h3 className="text-lg font-bold text-gray-900">New Message</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors bg-white rounded-full p-1 border border-gray-200">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>

            <form onSubmit={handleSend} className="flex-1 flex flex-col min-h-0">
                <div className="px-4 sm:px-6 py-4 space-y-4 overflow-y-auto flex-1">
                    <div className="space-y-2">
                        <div className="flex items-center gap-2 border-b border-gray-100 pb-2">
                            <span className="text-sm font-semibold text-gray-500 w-10">To</span>
                            <input 
                                type="text" 
                                value={to} 
                                onChange={e => setTo(e.target.value)}
                                className="flex-1 outline-none text-sm text-gray-800"
                                placeholder="recipient@example.com"
                                required 
                            />
                            <div className="flex gap-2 text-xs text-gray-500">
                                <button type="button" onClick={() => setShowCc(!showCc)} className="hover:text-gray-800 hover:underline">Cc</button>
                                <button type="button" onClick={() => setShowBcc(!showBcc)} className="hover:text-gray-800 hover:underline">Bcc</button>
                            </div>
                        </div>
                        {showCc && <div className="flex items-center gap-2 border-b border-gray-100 pb-2 animate-in fade-in slide-in-from-top-1"><span className="text-sm font-semibold text-gray-500 w-10">Cc</span><input type="text" value={cc} onChange={e => setCc(e.target.value)} className="flex-1 outline-none text-sm text-gray-800" placeholder="cc@example.com"/></div>}
                        {showBcc && <div className="flex items-center gap-2 border-b border-gray-100 pb-2 animate-in fade-in slide-in-from-top-1"><span className="text-sm font-semibold text-gray-500 w-10">Bcc</span><input type="text" value={bcc} onChange={e => setBcc(e.target.value)} className="flex-1 outline-none text-sm text-gray-800" placeholder="bcc@example.com"/></div>}
                        <div className="flex items-center gap-2 border-b border-gray-100 pb-2"><span className="text-sm font-semibold text-gray-500 w-10">Subject</span><input type="text" value={subject} onChange={e => setSubject(e.target.value)} className="flex-1 outline-none text-sm text-gray-800 font-medium" placeholder="Subject"/></div>
                    </div>

                    <div className="flex flex-col h-full min-h-[300px] border border-gray-200 rounded-lg overflow-hidden bg-white">
                        <RichTextToolbar onCmd={execCmd} onImage={handleInsertImage} />
                        <div ref={editorRef} contentEditable id="compose-editor" className="flex-1 p-4 outline-none overflow-y-auto text-sm font-sans" style={{ minHeight: '200px' }}></div>
                    </div>

                    {attachments.length > 0 && (
                        <div className="flex flex-wrap gap-2 pt-2">
                            {attachments.map((file, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-gray-100 px-3 py-1.5 rounded-full text-[10px] text-gray-700 border border-gray-200 shadow-sm">
                                    <svg className="w-3 h-3 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                                    <span className="max-w-[120px] truncate font-medium">{file.name}</span>
                                    <span className="text-gray-400 font-normal">({formatSize(file.size)})</span>
                                    <button type="button" onClick={() => removeAttachment(idx)} className="ml-1 p-0.5 hover:bg-gray-200 rounded-full transition-colors"><svg className="w-3 h-3 text-gray-400 hover:text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex justify-between items-center pb-safe">
                    <div className="flex items-center gap-3">
                         <input type="file" multiple ref={fileInputRef} className="hidden" onChange={handleFileSelect} />
                         <button type="button" onClick={() => fileInputRef.current?.click()} className="text-gray-500 hover:text-gray-900 hover:bg-gray-200 p-2 rounded-full transition-colors" title="Attach File"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg></button>
                    </div>
                    <div className="flex items-center gap-4 flex-1 justify-end">
                        {sending && (
                            <div className="flex-1 max-w-[150px] space-y-1">
                                <div className="flex justify-between text-[10px] font-bold text-gray-500">
                                    <span>{uploadProgress < 100 ? 'Uploading...' : 'Processing...'}</span>
                                    <span>{uploadProgress}%</span>
                                </div>
                                <div className="w-full h-1.5 bg-gray-200 rounded-full overflow-hidden">
                                    <div className="h-full bg-green-500 transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
                                </div>
                            </div>
                        )}
                        <button type="button" onClick={onClose} className="text-sm font-medium text-gray-500 hover:text-gray-800 transition-colors">Discard</button>
                        <button type="submit" disabled={sending} className="bg-green-600 text-white px-6 py-2 rounded-lg text-sm font-bold hover:bg-green-700 transition-colors disabled:opacity-50 flex items-center gap-2 shadow-sm">
                            {sending ? <Spinner /> : 'Send'}
                        </button>
                    </div>
                </div>
            </form>
        </div>
    </div>
  );
};

export default WebmailCompose;
